// src/lib/mcp/tools/list-blog-posts.ts
var list_blog_posts_default = defineTool({
  name: "list_blog_posts",
  title: "List blog posts",
  description: "List published blog posts on CognitionX (Russian-language CBT/schema-therapy blog by psychologist Dmitry Yatsko). Returns slug, title, description, date, and tags for each post. Filter by tag optionally.",
  inputSchema: {
    tag: z.string().optional().describe("Optional tag filter (case-insensitive substring match)."),
    limit: z.number().int().min(1).max(200).optional().describe("Max number of posts to return (default 50).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ tag, limit }) => {
    const t = tag?.toLowerCase();
    const filtered = mcpPosts.filter((p) => !t || p.tags.some((x) => x.toLowerCase().includes(t))).sort((a, b) => (b.date || "").localeCompare(a.date || "")).slice(0, limit ?? 50).map((p) => ({
      slug: p.slug,
      title: p.title,
      description: p.description,
      date: p.date,
      updatedAt: p.updatedAt,
      tags: p.tags,
      url: `https://cognitionx.cloud/blog/${p.slug}`
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(filtered, null, 2) }],
      structuredContent: { posts: filtered, total: filtered.length }
    };
  }
});

// src/lib/mcp/tools/get-blog-post.ts
import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.20.0";
import { z as z2 } from "npm:zod@^3.25.76";
var get_blog_post_default = defineTool2({
  name: "get_blog_post",
  title: "Get blog post",
  description: "Fetch the full plain-text body of a CognitionX blog post by its slug. Returns title, description, tags, dates, and markdown-like body.",
  inputSchema: {
    slug: z2.string().min(1).describe("Blog post slug, e.g. 'kpt-pri-depressii'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ slug }) => {
    const post = mcpPosts.find((p) => p.slug === slug);
    if (!post) {
      return {
        content: [{ type: "text", text: `No blog post with slug "${slug}".` }],
        isError: true
      };
    }
    const result = {
      slug: post.slug,
      title: post.title,
      description: post.description,
      date: post.date,
      updatedAt: post.updatedAt,
      tags: post.tags,
      url: `https://cognitionx.cloud/blog/${post.slug}`,
      body: post.body
    };
    return {
      content: [{ type: "text", text: `# ${post.title}

${post.description}

${post.body}` }],
      structuredContent: result
    };
  }
});

