      interpretation = "\u0412\u044B \u0441\u043A\u043B\u043E\u043D\u043D\u044B \u0432\u0438\u0434\u0435\u0442\u044C \u0441\u0435\u0431\u044F \u0432 \u043D\u0435\u0433\u0430\u0442\u0438\u0432\u043D\u043E\u043C \u0441\u0432\u0435\u0442\u0435 \u0438 \u043D\u0435\u0434\u043E\u043E\u0446\u0435\u043D\u0438\u0432\u0430\u0442\u044C \u0441\u0432\u043E\u0438 \u0441\u0438\u043B\u044C\u043D\u044B\u0435 \u0441\u0442\u043E\u0440\u043E\u043D\u044B.";
      recommendation = "\u041D\u0438\u0437\u043A\u0430\u044F \u0441\u0430\u043C\u043E\u043E\u0446\u0435\u043D\u043A\u0430 \u2014 \u0447\u0430\u0441\u0442\u044B\u0439 \u0441\u043F\u0443\u0442\u043D\u0438\u043A \u0434\u0435\u043F\u0440\u0435\u0441\u0441\u0438\u0438 \u0438 \u0442\u0440\u0435\u0432\u043E\u0433\u0438. \u0420\u0435\u043A\u043E\u043C\u0435\u043D\u0434\u0443\u0435\u0442\u0441\u044F \u0440\u0430\u0431\u043E\u0442\u0430 \u0441 \u043F\u0441\u0438\u0445\u043E\u043B\u043E\u0433\u043E\u043C: \u041A\u041F\u0422 \u0438 \u0441\u0445\u0435\u043C\u0430-\u0442\u0435\u0440\u0430\u043F\u0438\u044F.";
